#include "ksArpMainTask.h"
#include <array>
#include <iostream>
#include <random>
#include <stdexcept>
using T=ks::ArpMainTask;using S=T::Stage;using C=T::Child;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
uint16_t phaseOracle(uint32_t elapsed,uint32_t rate){const uint64_t cross=uint64_t(elapsed&65535)*(rate>>16)+uint64_t(rate&65535)*(elapsed>>16);return uint16_t(uint64_t(elapsed>>16)*(rate>>16)+(cross>>16));}
uint16_t durationOracle(unsigned shape,unsigned first,unsigned second){const unsigned bias=uint8_t(shape-64);if(bias&128){unsigned scale=uint8_t(uint8_t(0-bias)*4);if(!scale)scale=252;return uint16_t((first<<8)-scale*first);}return uint16_t((first<<8)+uint8_t(bias*4)*second);}
int main(){try{uint64_t cases=0;std::mt19937 rng(0x4b534152);auto verify=[&](uint32_t now,uint32_t previous,uint32_t acc,uint32_t rate,unsigned shape,unsigned firstDelay,unsigned secondDelay,unsigned thirdDelay,unsigned event,unsigned peek,unsigned gate,unsigned policy,unsigned oldPolicy,unsigned pedal,unsigned mode,unsigned oldMode,bool changePattern,unsigned latency){
 T t;unsigned reads=0,writes=0,stepCount=0,phaseWrites=0,durationWrites=0,loops=0;uint32_t previousState=previous,accState=acc;uint16_t phaseState=0;unsigned patternState=changePattern?1:0,gateState=gate,policyState=oldPolicy;bool reset=false;
 while(!t.complete()&&!t.handoff()){
  check(++loops<1000,"Pure main stalled");if(t.awaitingChild()){switch(t.child()){case C::Controls:check(t.resumeControls(19),"Controls reply rejected");break;case C::Part:check(t.resumePart(233),"Part reply rejected");break;case C::ReleaseHeld:check(t.resumeHeld(uint8_t(oldPolicy^policyState)),"Held reply rejected");break;case C::Step:{const auto word=stepCount==0?uint16_t(event<<8|firstDelay):stepCount==1?uint16_t(1<<8|secondDelay):uint16_t(peek<<8|thirdDelay);++stepCount;check(t.resumeStep(word,0xffa12345u+stepCount*2),"Step reply rejected");break;}case C::ResetPattern:accState=0;phaseState=0;gateState=0;reset=true;check(t.resumeChild(),"Reset reply rejected");break;default:check(t.resumeChild(),"Child reply rejected");break;}continue;}
  auto read=[&](S stage)->uint32_t{++reads;switch(stage){case S::ReadPatch:case S::ReadCurrentPatch:return 0xffa23456u;case S::ReadTempo:return 127;case S::ReadVelocity:return 97;case S::ReadGate:case S::ReadGateShape:return shape;case S::ReadModeIndex:return 9;case S::ReadModeTable:return mode;case S::ReadOldMode:return oldMode;case S::ReadPolicy:return policy;case S::ReadOldPolicy:return oldPolicy;case S::ReadPedal:return pedal;case S::ReadReleasedMode:case S::ReadEnabledMode:case S::ReadGateMode:case S::ReadPatternMode:case S::ReadFinalMode:return mode;case S::ReadClock:return now;case S::ReadPreviousClock:return previousState;case S::ReadAccumulator:return accState;case S::ReadRate:return rate;case S::ReadOldPhase:return phaseState;case S::ReadPatternIndex:return 0;case S::ReadOldPatternIndex:return patternState;case S::ReadPatternReference:check(t.patternIndex()==0,"Pattern index differed");return 0xffa00001;case S::ReadPatternHeader:return 0x0801;case S::ReadCurrentPhase:case S::ReadRestPhase:case S::ReadNotePhase:return phaseState>>8;case S::ReadNextGate:return gateState;case S::ReadPeekStep:check(t.stepReference()==0xffa12349u,"Pattern lookahead reference differs");return peek<<8|thirdDelay;case S::ReadNotePolicy:return policyState;default:throw std::runtime_error("Unexpected pure read");}};
  auto write=[&](S stage,uint32_t data){++writes;switch(stage){case S::PublishPolicy:policyState=data;check(data==uint8_t(policy|((policy&4)?pedal:0)),"Pedal policy union differs");break;case S::PublishOctaves:check(data==(policyState&3),"Octaves differ");break;case S::PublishClock:previousState=data;check(data==now,"Clock publication differs");break;case S::PublishAccumulator:accState=data;check(data==(phaseWrites?0:uint32_t(now-previous+acc)),"Elapsed wrap accumulator differs");break;case S::PublishPhase:{phaseState=uint16_t(data);const auto expected=phaseWrites?0:phaseOracle(uint32_t(now-previous+acc),rate);check(data==expected,"High/cross fixed-point phase differs");++phaseWrites;break;}case S::PublishPatternIndex:patternState=data;break;case S::PublishPatternLength:check(data==8,"Pattern header length differs");break;case S::PublishPatternReference:check(data==0xffa00003u,"Pattern reference increment differs");break;case S::PublishRestGate:gateState=data;check(data==uint8_t((phaseState>>8)+firstDelay),"Rest gate differs");break;case S::ReadEventVelocity:check(data==event,"Event velocity differs");break;case S::PublishNoteGate:{gateState=data;const unsigned second=uint8_t(secondDelay+(peek?0:thirdDelay));check(data==uint8_t((phaseState>>8)+firstDelay+second),"Note gate byte wrap differs");break;}case S::PublishDuration:{const unsigned second=uint8_t(secondDelay+(peek?0:thirdDelay));check(data==durationOracle(shape,firstDelay,second),"Signed gate interpolation differs");++durationWrites;break;}default:break;}};
  auto timing=[&](S,bool word){return word?6u:latency;};const auto cost=t.nextClocks(t.publication()?latency:3,t.dynamicWordRead()?6:3);check(cost>0,"Main deadline stalled");const auto before=reads+writes;check(!t.advanceBefore(cost-1,read,write,timing)&&reads+writes==before,"Early main access");check(t.advanceBefore(cost,read,write,timing)==cost,"Main deadline rejected");
 }
 check(phaseWrites==(changePattern&&!(mode&64)?2:1),"Clock repeat count differs");check(t.handoff()==bool(mode&64),"Mono tail selection differs");if(!(mode&64)){const unsigned phaseByte=phaseState>>8,distance=uint8_t(phaseByte-(reset?0:gate));const bool admitted=!(distance&128)&&phaseByte>=(reset?0:gate);check(stepCount==(!admitted?0:!event?1:peek?2:3),"Step/lookahead count differs");check(durationWrites==unsigned(admitted&&event),"Gate duration admission differs");}
 ++cases;};
 for(unsigned shape=0;shape<256;++shape)for(unsigned firstDelay=0;firstDelay<256;++firstDelay)for(unsigned variant=0;variant<4;++variant)verify(0,0,0,0x10000,shape,firstDelay,variant&1?255:128,127,variant!=0,variant&1,0,variant&2?4:0,0,16,0,0,false,variant&1?0:3);
 for(unsigned i=0;i<262144;++i)verify(rng(),rng(),rng(),rng(),rng()&255,rng()&255,rng()&255,rng()&255,rng()&1,rng()&1,rng()&255,rng()&255,rng()&255,rng()&255,i&1?64:0,i&2?64:0,i&4,i&8?0:3);
 std::cout<<"PASS: "<<cases<<" pure arp refresh/gate tasks, independent 64-bit cross-product oracle, all gate-shape/first-delay bytes, signed interpolation, wrapped clocks/gates, policy/mono/pattern/child replies and early deadlines\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
